//! Byte-for-byte parity with the verified Python encoder for identical canonical bitmaps.
//! Fixtures: fixtures/sc03h/vectors.json, generated by poc/python/tools/gen_fixtures.py.

use nuprint_protocol::iprint::{FrameDecoder, Iprint5178Driver, Iprint5178Params, command, crc8};
use nuprint_protocol::{Density, MonoBitmap, PrintRequest};
use serde_json::Value;

fn vectors() -> Value {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../../fixtures/sc03h/vectors.json");
    serde_json::from_str(&std::fs::read_to_string(path).expect("fixture present")).unwrap()
}

fn driver() -> Iprint5178Driver {
    Iprint5178Driver::new(Iprint5178Params::sc03h_reference()).unwrap()
}

#[test]
fn crc_and_command_frames_match() {
    let v = vectors();
    assert_eq!(u64::from(crc8(b"123456789")), v["crc8_check"]["crc"].as_u64().unwrap());
    for c in v["commands"].as_array().unwrap() {
        let op = c["opcode"].as_u64().unwrap() as u8;
        let payload = hex::decode(c["payload_hex"].as_str().unwrap()).unwrap();
        assert_eq!(hex::encode(command(op, &payload)), c["frame_hex"].as_str().unwrap(), "opcode {op:02x}");
    }
}

#[test]
fn captured_responses_decode() {
    for r in vectors()["responses"].as_array().unwrap() {
        let frames = FrameDecoder::new().feed(&hex::decode(r["hex"].as_str().unwrap()).unwrap());
        assert_eq!(frames.len(), 1, "{}", r["name"]);
        assert_eq!(u64::from(frames[0].opcode), r["opcode"].as_u64().unwrap());
        assert_eq!(hex::encode(&frames[0].payload), r["payload_hex"].as_str().unwrap());
    }
}

#[test]
fn every_job_vector_matches_python_bytes() {
    let v = vectors();
    let d = driver();
    let jobs = v["jobs"].as_array().unwrap();
    assert!(jobs.len() >= 40);
    for job in jobs {
        let name = job["bitmap"].as_str().unwrap();
        let b = &v["bitmaps"][name];
        let bitmap = MonoBitmap::from_packed(
            b["width"].as_u64().unwrap() as u32,
            b["height"].as_u64().unwrap() as u32,
            hex::decode(b["rows_hex"].as_str().unwrap()).unwrap(),
        )
        .unwrap();
        let density: Density = job["darkness"].as_str().unwrap().parse().unwrap();
        let feed = job["feed_mm"].as_u64().unwrap() as u16;
        let bytes = d.encode_job(&PrintRequest { bitmap: &bitmap, density, trailing_feed_mm: feed }).unwrap();
        assert_eq!(hex::encode(&bytes), job["job_hex"].as_str().unwrap(), "{name} {density:?} feed {feed}");
    }
}
